prog = '''from collections import deque, Counter

def transform(grid):
    a = [row[:] for row in grid]
    h, w = len(a), len(a[0])
    bg = Counter(v for row in a for v in row).most_common(1)[0][0]
    # Find near-solid rectangular objects; a single foreign pixel inside a
    # rectangle is a hole in the object and should be restored to its color.
    seen = set()
    rectangles = []
    for r in range(h):
        for c in range(w):
            color = a[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and a[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            rs = [y for y,x in cells]; cs = [x for y,x in cells]
            y0,y1,x0,x1 = min(rs),max(rs),min(cs),max(cs)
            area = (y1-y0+1)*(x1-x0+1)
            if area >= 4 and len(cells) >= area-1:
                rectangles.append((color,y0,y1,x0,x1,area-len(cells)))
    # Replace only the missing cell of a nearly complete rectangle.
    for color,y0,y1,x0,x1,missing in rectangles:
        if missing == 1:
            for y in range(y0,y1+1):
                for x in range(x0,x1+1):
                    if a[y][x] != color:
                        a[y][x] = color
    # Remove remaining isolated non-background pixels (noise on the field).
    for r in range(h):
        for c in range(w):
            if a[r][c] == bg:
                continue
            color = a[r][c]
            if all(not (0 <= y < h and 0 <= x < w and a[y][x] == color)
                   for y,x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))):
                a[r][c] = bg
    return a
'''
